template <typename W, bool INDEX_SRC>
sycl::event indexed_copy(sycl::queue& q, const W* src, W* dst, const int* index,
                         std::size_t n, std::size_t row) {
  return q.parallel_for(sycl::range<2>(n, row), [=](sycl::id<2> id) {
