template <typename T>
inline void stage_weight_tile(int lane, const std::uint8_t *rows,
                              const std::uint8_t *scales,
                              std::size_t row_bytes, std::size_t scale_stride,
                              std::size_t n0, std::size_t n_limit,
                              std::size_t k0, std::size_t k_limit, T *bs) {
