    const std::size_t kk = static_cast<std::size_t>(e) / TN;
    const std::size_t nn = static_cast<std::size_t>(e) % TN;
    const std::size_t gk = k0 + kk;
    const std::size_t gn = n0 + nn;
    float value = 0.0f;
