def _cpu_b70_partial(
    bank: Int4ExpertBank,
    layer: int,
    x: torch.Tensor,
    ids: torch.Tensor,
    weights: torch.Tensor,
) -> torch.Tensor:
    x = x.float()
    weights = weights.float()
    result = torch.zeros(x.shape[0], bank.hidden, dtype=torch.float32)
    cache: dict[tuple[int, int], torch.Tensor] = {}
    for row in range(ids.shape[0]):
